INSERT INTO interview_turn (
    session_id, client_turn_id, sequence_no, prompt, answer_text, score, feedback,
    accuracy_score, completeness_score, depth_score, expression_score
) VALUES (
    #{sessionId}, #{request.clientTurnId}, #{sequenceNo}, #{prompt}, #{request.answerText},
    #{score.total}, #{feedback}, #{score.accuracy}, #{score.completeness},
    #{score.depth}, #{score.expression}
)
RETURNING id
